#define CONTROLLED_READOUT_LIBRARY
#include "train_controlled_readout.cu"

void refeature(Data& data,ServerCore& core){data.x.clear();for(auto& r:data.records){SelfDecodingNode<16,256> node;for(int id:r.input)node.push(id,[&](int id){return core.q1.code(id);});auto view=node;float mix[256]={};for(int k=0;;++k){for(int d=0;d<256;++d)mix[d]+=core.reader_sel[k*256+d]*view.trit[d];if(!view.count)break;view.pop([&](int id){return core.q1.code(id);});}data.x.insert(data.x.end(),mix,mix+256);for(int i=0;i<64;++i)data.x.push_back(float((node.hash>>(4*(i&7)))&15)/15-.5f);data.x.push_back(1);}}
void production(const char* tag,const Data& data,ServerCore& core){for(int query=900;query<907;++query){int n=0,top=0,binary=0;double loss=0;std::vector<float>z;for(const auto&r:data.records)if(r.input[63]==query){core.forward_window(std::vector<int>(r.input.begin(),r.input.end()),z);float mx=*std::max_element(z.begin(),z.end());double s=0;for(float v:z)s+=std::exp(double(v)-mx);loss+=mx+std::log(s)-z[r.target];top+=std::max_element(z.begin(),z.end())-z.begin()==r.target;binary+=z[r.target]>z[r.alternate];++n;}printf("PRODUCTION %s query=%d CE=%.9f full1024_top1=%.6f binary=%.6f\n",tag,query,loss/n,double(top)/n,double(binary)/n);}}
int main(int argc,char**argv){try{if(argc!=2)return 1;setvbuf(stdout,nullptr,_IONBF,0);std::string root=argv[1];ServerCore core;if(!core.load("tao_fixed_step50002.bin","tao_context_supported.tcg","tao_coef_rts1_128.reader","tinystories_train.txt","experiments/d256_nibble64_baseline/train_tokens.bin"))return 2;auto data=load(root+"/test_context.bin",core);for(int control=0;control<3;++control){auto altered=data;for(auto&r:altered.records)if(r.distance<64){if(control==1)r.input[63-r.distance]=3;if(control==2)r.input[63-r.distance]=r.alternate;}refeature(altered,core);const char*tag=control==0?"original":control==1?"no_key":"swapped_key_wrong_label";for(int seed:{42,123,2026}){std::vector<float>w(Classes*Features);std::ifstream in(root+"/readout_seed"+std::to_string(seed)+".bin",std::ios::binary);in.read((char*)w.data(),w.size()*4);if(!in)throw std::runtime_error("missing weights");printf("READOUT_SEED %d CONTROL %s\n",seed,tag);evaluate(tag,altered,w);}production(tag,altered,core);}return 0;}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 10;}}
